let source = "";
for await (const chunk of process.stdin) source += chunk;
const input = JSON.parse(source || "{}");

const json = { "content-type": "application/json" };
const accounts = (f, t) => [
  { id: input.fromId, balance: f.balance, version: f.version },
  { id: input.toId, balance: t.balance, version: t.version }
];
const before = {
  from: { balance: input.fromBalance, version: input.fromVersion },
  to: { balance: input.toBalance, version: input.toVersion }
};

function emit(out) {
  console.log(JSON.stringify(out));
}

function fail(status, code, retryable, message) {
  emit({
    http: { status, headers: json, body: { error: code, message } },
    database: { accounts: accounts(before.from, before.to), transaction: { committed: false, rolledBack: true } },
    messages: [],
    ordering: [],
    failures: [{ code, status, retryable }],
    retryability: retryable
  });
}

const amount = input.amount;
const currentFrom = input.currentFromVersion ?? input.fromVersion;
const currentTo = input.currentToVersion ?? input.toVersion;
const expectedFrom = input.expectedFromVersion ?? input.fromVersion;
const expectedTo = input.expectedToVersion ?? input.toVersion;

if (!Number.isInteger(amount) || amount <= 0 || !input.fromId || !input.toId || input.fromId === input.toId) {
  fail(400, "invalid_transfer", false, "Invalid transfer request");
} else if (input.replay || input.existingTransfer) {
  const prior = input.existingTransfer ?? {};
  const body = prior.body ?? {
    transferId: input.transferId,
    fromBalance: input.fromBalance,
    toBalance: input.toBalance,
    fromVersion: input.fromVersion,
    toVersion: input.toVersion
  };
  emit({
    http: { status: 200, headers: { ...json, "idempotent-replay": "true" }, body },
    database: { accounts: accounts(before.from, before.to), transaction: { committed: false, replayed: true } },
    messages: [],
    ordering: ["idempotency-check"],
    failures: [],
    retryability: false
  });
} else if (currentFrom !== expectedFrom || currentTo !== expectedTo) {
  fail(409, "version_conflict", true, "Account version conflict");
} else if (input.fromBalance < amount) {
  fail(422, "insufficient_funds", false, "Insufficient funds");
} else {
  const fromBalance = input.fromBalance - amount;
  const toBalance = input.toBalance + amount;
  const fromVersion = input.fromVersion + 1;
  const toVersion = input.toVersion + 1;
  emit({
    http: {
      status: 201,
      headers: json,
      body: { transferId: input.transferId, fromBalance, toBalance, fromVersion, toVersion }
    },
    database: {
      accounts: accounts({ balance: fromBalance, version: fromVersion }, { balance: toBalance, version: toVersion }),
      transaction: { committed: true }
    },
    messages: [{
      type: "transfer.completed",
      transferId: input.transferId,
      fromId: input.fromId,
      toId: input.toId,
      amount
    }],
    ordering: ["idempotency-check", "debit", "credit", "commit", "publish"],
    failures: [],
    retryability: false
  });
}

