  if (/^expected.*version/i.test(k) && /from/i.test(k) && v !== input.fromVersion) conflict = true;
  if (/^expected.*version/i.test(k) && /to/i.test(k) && !/from/i.test(k) && v !== input.toVersion) conflict = true;
}

